-- The official arms and seals of UST's academic units (src/lib/governance/unit-emblems.ts), with where each
-- file came from. Keyed by the UST directory key (src/lib/governance/ust-directory.ts). The image files are
-- served from public/brand/units; sha256 is of that served file. Only the Hub's server reads it, with the
-- secret key, like the governance store.

create table public.unit_emblems (
  unit_key text primary key check (unit_key ~ '^[A-Z][0-9]{2,3}$'),
  file_path text not null unique,
  form text not null check (form in ('shield', 'seal')),
  width integer not null check (width > 0),
  height integer not null check (height > 0),
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  -- Where the artwork was published, the original file, and an archived copy of it.
  source text not null,
  source_page text not null,
  source_url text not null,
  archive_url text,
  license text not null,
  retrieved_at date not null,
  updated_at timestamptz not null default now()
);

alter table public.unit_emblems enable row level security;
revoke all on table public.unit_emblems from anon, authenticated;

